import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { caseHash, compare, engineRects, flatten, type LayoutCase, type Rect4 } from "../../layout/conformance/case";
import { readFixtures } from "../../layout/conformance/fixtures";
import { DocumentLayout } from "../src";
import { documentCases } from "./conformance/cases";

/**
 * Documents against Chromium: every node of a document is rendered in
 * Chromium as a div with the CSS `cssDeclarations` states for it
 * (test/conformance/chromium.json, regenerated by `npm run
 * conformance:update`). Both the layout engine run on that CSS and the
 * bridge's DocumentLayout must produce the same boxes within 1 px: what the
 * editor draws is what the exported CSS renders in a browser.
 */

const fixtures = readFixtures(join(process.cwd(), "packages", "document", "test", "conformance", "chromium.json"));
const cases = documentCases();

describe("document CSS conformance (Chromium fixtures)", () => {
  it("has a fixture for every case", () => {
    expect(cases.filter((c) => fixtures.cases[c.case.name]?.hash !== caseHash(c.case)).map((c) => c.case.name), "run `npm run conformance:update`").toEqual([]);
  });

  let within1 = 0;
  let within001 = 0;
  let boxes = 0;
  for (const dc of cases) {
    it(dc.case.name, () => {
      const ref = fixtures.cases[dc.case.name]!;
      // The engine on the stated CSS.
      const actual = engineRects(dc.case);
      const engine = compare(dc.case, ref.rects, actual);
      if (process.env.CONFORMANCE_DEBUG && dc.case.name.includes(process.env.CONFORMANCE_DEBUG)) console.log(dump(dc.case, ref.rects, actual));
      expect(engine.maxError, `engine box #${engine.worst?.index}: expected ${JSON.stringify(engine.worst?.expected)}, got ${JSON.stringify(engine.worst?.actual)}`).toBeLessThanOrEqual(1);
      // The bridge's layout of the document itself.
      const layout = new DocumentLayout(dc.doc, dc.page);
      const rects: Rect4[] = [[0, 0, 0, 0]];
      for (const id of dc.ids) {
        let x = 0;
        let y = 0;
        for (let p: string | undefined = id; p !== undefined && p !== dc.page; p = dc.doc.tree.parentOf(p)) {
          const b = layout.box(p)!;
          x += b.x;
          y += b.y;
        }
        const b = layout.box(id)!;
        rects.push([x, y, b.width, b.height]);
      }
      const bridge = compare(dc.case, ref.rects, rects);
      boxes += bridge.boxes;
      within1 += bridge.within1;
      within001 += bridge.within001;
      expect(bridge.maxError, `bridge box #${bridge.worst?.index}: expected ${JSON.stringify(bridge.worst?.expected)}, got ${JSON.stringify(bridge.worst?.actual)}`).toBeLessThanOrEqual(1);
    });
  }

  it("reports", () => {
    console.log(`[document css conformance] ${cases.length} documents, boxes within 1px ${within1}/${boxes}, within 0.01px ${within001}/${boxes}`);
  });
});

function dump(c: LayoutCase, expected: readonly Rect4[], actual: readonly Rect4[]): string {
  const lines = [c.name];
  const nodes = flatten(c.root);
  const depth = new Map<unknown, number>([[c.root, 0]]);
  for (const n of nodes) for (const ch of n.children ?? []) depth.set(ch, depth.get(n)! + 1);
  const r = (v: readonly number[] | undefined): string => (v ? v.map((x) => Math.round(x * 100) / 100).join(",") : "-");
  nodes.forEach((n, i) => {
    const bad = expected[i]!.some((v, k) => Math.abs(v - actual[i]![k]!) > 1);
    lines.push(`${bad ? "!!" : "  "} ${"  ".repeat(depth.get(n)!)}#${i} {${n.style ?? ""}}\n${" ".repeat(4 + 2 * depth.get(n)!)}chromium ${r(expected[i])}  engine ${r(actual[i])}`);
  });
  return lines.join("\n");
}
